#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\"\"\"\nCREADOR DE BASE DE DATOS CON MIGRACIÓN COMPLETA\n==============================================\n\nEste script crea la base de datos con la estructura correcta,\nincluyendo la columna fecha_creacion en la tabla etiquetas.\n\"\"\"\n\nimport sqlite3\nimport os\nfrom datetime import datetime\n\ndef crear_base_datos_completa():\n    \"\"\"Crear base de datos con estructura completa\"\"\"\n    print(\"🗄️ CREANDO BASE DE DATOS COMPLETA\")\n    print(\"=\" * 45)\n    \n    try:\n        # Conectar/crear base de datos\n        conn = sqlite3.connect('crm_legal.db')\n        cursor = conn.cursor()\n        \n        print(\"📋 Creando tabla etiquetas con estructura completa...\")\n        \n        # Crear tabla etiquetas con estructura completa\n        cursor.execute('''\n            CREATE TABLE IF NOT EXISTS etiquetas (\n                id_etiqueta INTEGER PRIMARY KEY AUTOINCREMENT,\n                nombre_etiqueta TEXT NOT NULL UNIQUE COLLATE NOCASE,\n                descripcion TEXT DEFAULT '',\n                color TEXT DEFAULT '#3498db',\n                tipo TEXT DEFAULT 'general',\n                fecha_creacion TEXT DEFAULT CURRENT_TIMESTAMP\n            )\n        ''')\n        \n        print(\"✅ Tabla etiquetas creada\")\n        \n        # Crear otras tablas básicas necesarias\n        cursor.execute('''\n            CREATE TABLE IF NOT EXISTS clientes (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                nombre TEXT NOT NULL,\n                direccion TEXT,\n                email TEXT,\n                whatsapp TEXT,\n                created_at INTEGER,\n                etiquetas TEXT DEFAULT \"\"\n            )\n        ''')\n        \n        cursor.execute('''\n            CREATE TABLE IF NOT EXISTS casos (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                cliente_id INTEGER NOT NULL,\n                numero_expediente TEXT,\n                anio_caratula TEXT,\n                caratula TEXT NOT NULL,\n                juzgado TEXT,\n                jurisdiccion TEXT,\n                etapa_procesal TEXT,\n                notas TEXT,\n                ruta_carpeta TEXT,\n                ruta_documentos TEXT,\n                inactivity_threshold_days INTEGER DEFAULT 30,\n                inactivity_enabled INTEGER DEFAULT 1,\n                etiquetas TEXT DEFAULT \"\",\n                FOREIGN KEY (cliente_id) REFERENCES clientes(id) ON DELETE CASCADE\n            )\n        ''')\n        \n        cursor.execute('''\n            CREATE TABLE IF NOT EXISTS audiencias (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                caso_id INTEGER NOT NULL,\n                fecha TEXT NOT NULL,\n                hora TEXT,\n                link TEXT,\n                descripcion TEXT,\n                recordatorio_activo INTEGER DEFAULT 1,\n                recordatorio_minutos INTEGER DEFAULT 30,\n                FOREIGN KEY (caso_id) REFERENCES casos(id) ON DELETE CASCADE\n            )\n        ''')\n        \n        print(\"✅ Tablas básicas creadas\")\n        \n        # Insertar etiquetas predefinidas\n        etiquetas_predefinidas = [\n            ('Urgente', 'Casos que requieren atención inmediata', '#e74c3c', 'prioridad'),\n            ('Alta', 'Casos de alta prioridad', '#f39c12', 'prioridad'),\n            ('Media', 'Casos de prioridad media', '#f1c40f', 'prioridad'),\n            ('Baja', 'Casos de baja prioridad', '#2ecc71', 'prioridad'),\n            ('Civil', 'Casos de derecho civil', '#34495e', 'tipo'),\n            ('Penal', 'Casos de derecho penal', '#c0392b', 'tipo'),\n            ('Laboral', 'Casos de derecho laboral', '#16a085', 'tipo'),\n            ('Familia', 'Casos de derecho de familia', '#e67e22', 'tipo')\n        ]\n        \n        for nombre, desc, color, tipo in etiquetas_predefinidas:\n            try:\n                cursor.execute('''\n                    INSERT OR IGNORE INTO etiquetas \n                    (nombre_etiqueta, descripcion, color, tipo, fecha_creacion)\n                    VALUES (?, ?, ?, ?, ?)\n                ''', (nombre, desc, color, tipo, datetime.now().isoformat()))\n            except:\n                pass  # Si ya existe, ignorar\n        \n        print(f\"✅ {len(etiquetas_predefinidas)} etiquetas predefinidas agregadas\")\n        \n        # Verificar que funciona la consulta con fecha_creacion\n        cursor.execute(\"SELECT nombre_etiqueta, fecha_creacion FROM etiquetas LIMIT 1\")\n        test_result = cursor.fetchone()\n        \n        if test_result:\n            print(f\"✅ Consulta de verificación exitosa: {test_result}\")\n        \n        conn.commit()\n        conn.close()\n        \n        print(\"\\n🎉 BASE DE DATOS CREADA EXITOSAMENTE\")\n        print(\"=\" * 45)\n        print(\"✅ Tabla etiquetas con columna fecha_creacion\")\n        print(\"✅ Tablas básicas (clientes, casos, audiencias)\")\n        print(\"✅ Etiquetas predefinidas insertadas\")\n        print(\"✅ Sin errores de 'no such column: fecha_creacion'\")\n        \n        return True\n        \n    except Exception as e:\n        print(f\"❌ Error creando base de datos: {e}\")\n        return False\n\ndef verificar_estructura_bd():\n    \"\"\"Verificar la estructura de la base de datos creada\"\"\"\n    print(\"\\n🔍 VERIFICANDO ESTRUCTURA BD\")\n    print(\"=\" * 35)\n    \n    try:\n        conn = sqlite3.connect('crm_legal.db')\n        cursor = conn.cursor()\n        \n        # Verificar tabla etiquetas\n        cursor.execute(\"PRAGMA table_info(etiquetas)\")\n        columnas = cursor.fetchall()\n        \n        print(\"📋 Estructura tabla etiquetas:\")\n        for col in columnas:\n            print(f\"   • {col[1]} ({col[2]})\")\n        \n        # Verificar datos\n        cursor.execute(\"SELECT COUNT(*) FROM etiquetas\")\n        count = cursor.fetchone()[0]\n        print(f\"\\n📊 Total etiquetas: {count}\")\n        \n        # Probar consulta con fecha_creacion\n        cursor.execute(\"SELECT nombre_etiqueta, fecha_creacion FROM etiquetas LIMIT 3\")\n        etiquetas = cursor.fetchall()\n        \n        print(\"\\n📋 Etiquetas de prueba:\")\n        for etiqueta in etiquetas:\n            print(f\"   • {etiqueta[0]} (creada: {etiqueta[1]})\")\n        \n        conn.close()\n        return True\n        \n    except Exception as e:\n        print(f\"❌ Error verificando BD: {e}\")\n        return False\n\ndef main():\n    \"\"\"Función principal\"\"\"\n    print(\"🗄️ CREADOR DE BD CON MIGRACIÓN - CRM LEGAL\")\n    print(\"=\" * 60)\n    \n    # Verificar si ya existe\n    if os.path.exists('crm_legal.db'):\n        print(\"⚠️ crm_legal.db ya existe\")\n        respuesta = input(\"¿Quieres recrearla? (s/N): \").lower()\n        if respuesta == 's':\n            backup_name = f\"crm_legal_backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}.db\"\n            os.rename('crm_legal.db', backup_name)\n            print(f\"💾 Backup creado: {backup_name}\")\n        else:\n            print(\"❌ Operación cancelada\")\n            return\n    \n    # Crear base de datos\n    if crear_base_datos_completa():\n        verificar_estructura_bd()\n        \n        print(\"\\n🚀 PRÓXIMOS PASOS:\")\n        print(\"1. Ejecuta: python main_app_refactorizado.py\")\n        print(\"2. Ya no deberían aparecer errores de fecha_creacion\")\n        print(\"3. Sistema de etiquetas completamente funcional\")\n        \n    else:\n        print(\"❌ Error creando base de datos\")\n\nif __name__ == \"__main__\":\n    main()\n